css:
/* 多巴胺糖果 · Dopamine
   奶油底 + 高饱和糖果色 + 大圆角 + 彩色投影。按钮、卡片、标签轮换撞色，
   目标是让界面本身像一颗糖。仅靠 CSS 与伪元素，不动数据。 */

html[data-theme] {
  color-scheme: light;
  --bg: #fff6f1;
  --ink: #241a2e; --muted: #6d5b7a; --dim: #92829e;
  --soft: #3d2c4c; --meta: #6d5b7a; --bright: #1a1226;
  --line: #ffd9e6; --line2: #ffe9f0;
  --accent: #ff77c8; --accent2: #8b6bff; --accentText: #ffffff;
  --good: #2fcfa0; --warn: #ffb347;
  --glow1: rgba(255, 119, 200, 0.3); --glow2: rgba(139, 107, 255, 0.26);
  --panel: #ffffff; --panel2: #fff1f7;
  --dock1: rgba(255, 255, 255, 0.92); --dock2: rgba(255, 250, 253, 0.96);
  --glass: rgba(255, 255, 255, 0.78);
  --track: #ffe0ec; --scroll: #ffb3d9; --coverbg: #ffe9f4;
  --menu: #ffffff; --menu1: #fff4f9; --menu2: #ffffff; --chev: #b58bd0;
  --edge: #ffc0e0; --edge2: #c4a9ff;
  --hover: #fff0f7; --tick: #ffd0e6;
  --inset: rgba(255, 255, 255, 0.9); --wordactive: #2b1338; --swborder: #ff9ed6;
  --shadow-dock: 0 30px 70px -34px rgba(255, 119, 200, 0.55), inset 0 1px 0 #ffffff;
  --serif: "Varela Round", "Nunito", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  --bottom: 140px;
  --shell-nav: #b39dff; --shell-nav2: #ff9ecb;
  --shell-navin: #ffffff; --shell-navmuted: rgba(255, 255, 255, 0.82); --shell-navline: rgba(255, 255, 255, 0.4);
}

html[data-theme] body {
  background:
    radial-gradient(680px 460px at 6% -6%, #ffe14d 0%, transparent 58%),
    radial-gradient(720px 480px at 96% -10%, #8fe9ff 0%, transparent 60%),
    radial-gradient(760px 520px at 66% 108%, #ffb3d9 0%, transparent 62%),
    linear-gradient(170deg, #fff8f2, #fff1f8 50%, #f6f1ff);
}
html[data-theme] body::before, html[data-theme] body::after { content: none; }

/* 侧栏：糖果渐变块 */
html[data-theme] .sidebar {
  margin: 14px 0 14px 14px; padding: 22px 14px; border: 0; border-radius: 30px;
  background: linear-gradient(165deg, #b39dff, #ff9ecb 96%);
  box-shadow: 0 26px 50px -28px rgba(139, 107, 255, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.5);
}
html[data-theme] .brand { padding: 2px 8px 20px; border-bottom: 1px solid rgba(255, 255, 255, 0.35); margin-bottom: 14px; }
html[data-theme] .brand .brand-name, html[data-theme] .brand strong { font-weight: 800; letter-spacing: 0.02em; color: #fff; }
html[data-theme] .nav button {
  border-radius: 999px; padding: 10px 14px; color: rgba(255, 255, 255, 0.85); font-weight: 600;
}
html[data-theme] .nav button:hover { background: rgba(255, 255, 255, 0.22); color: #fff; }
html[data-theme] .nav button.active {
  background: #ffffff; color: #6a3df0; box-shadow: 0 10px 22px -14px rgba(58, 20, 120, 0.6);
}

/* 顶栏：白胶囊 */
html[data-theme] .topbar {
  margin-top: 16px; padding: 0 20px; height: 64px; border: 0; border-radius: 999px;
  background: rgba(255, 255, 255, 0.86); box-shadow: 0 18px 40px -30px rgba(139, 107, 255, 0.6), inset 0 1px 0 #fff;
  backdrop-filter: blur(22px) saturate(180%);
}
html[data-theme] .search-global { border: 0; border-radius: 999px; background: #fff0f8; }
html[data-theme] .icon-btn { border: 0; border-radius: 999px; background: #fff0f8; }
html[data-theme] .icon-btn:hover { background: #ffe14d; }

/* 首页：糖纸便当 */
html[data-theme] .ledger-mast {
  margin-top: 22px; padding: 34px; border: 0; border-radius: 36px;
  background:
    radial-gradient(520px 320px at 84% -20%, #ffe14d 0%, transparent 62%),
    linear-gradient(140deg, #ffffff, #fff0f9 60%, #f3ecff);
  box-shadow: 0 34px 70px -44px rgba(139, 107, 255, 0.55), inset 0 1px 0 #fff;
}
html[data-theme] .ledger-mast h1, html[data-theme] .ledger-mast .mast-title {
  font-family: var(--serif); font-size: clamp(36px, 5vw, 68px); line-height: 1.02; letter-spacing: -1.4px;
  background: none; color: #ff2fa6; -webkit-text-fill-color: #ff2fa6;
}
html[data-theme] .ledger-mast h1 em {
  background: none; color: #6a3df0; -webkit-text-fill-color: #6a3df0;
}
html[data-theme] .ledger-mast p, html[data-theme] .subtitle { color: #6d5b7a; }

/* 卡片：白底大圆角 + 彩色投影，按位置轮换 */
html[data-theme] .card, html[data-theme] .pod-card, html[data-theme] .continue {
  border: 0; border-radius: 28px; background: #ffffff;
  box-shadow: 0 26px 50px -34px rgba(255, 119, 200, 0.45);
}
html[data-theme] .pod-card:nth-child(3n+1) { box-shadow: 0 26px 50px -34px rgba(255, 161, 61, 0.5); }
html[data-theme] .pod-card:nth-child(3n+2) { box-shadow: 0 26px 50px -34px rgba(23, 184, 255, 0.5); }
html[data-theme] .pod-card:hover, html[data-theme] .continue:hover { transform: translateY(-4px); }
html[data-theme] .btn { border: 0; border-radius: 999px; background: #ffe14d; color: #241a2e; font-weight: 800; }
html[data-theme] .btn.primary { background: linear-gradient(96deg, #ff77c8, #8b6bff); color: #ffffff; }

/* 统计：糖果数字 */
html[data-theme] #page-stats .page-head {
  margin: 18px 0; padding: 30px 32px; border: 0; border-radius: 36px;
  background: linear-gradient(140deg, #fff, #ffe8f4 58%, #e9e2ff);
  box-shadow: 0 30px 60px -42px rgba(139, 107, 255, 0.5);
}
html[data-theme] #page-stats .page-head h1 {
  font-size: clamp(30px, 4vw, 50px); letter-spacing: -1px;
  background: linear-gradient(96deg, #ff4fb0, #8b6bff 60%, #17b8ff);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
html[data-theme] #page-stats .eyebrow { color: #ff4fb0; letter-spacing: 0.26em; }
html[data-theme] #statsCards .stat:nth-child(1) { background: linear-gradient(150deg, #fff3b0, #ffe14d); }
html[data-theme] #statsCards .stat:nth-child(2) { background: linear-gradient(150deg, #d8f6ff, #8fe9ff); }
html[data-theme] #statsCards .stat:nth-child(3) { background: linear-gradient(150deg, #ffe0f2, #ff9ed6); }
html[data-theme] #page-stats .stat {
  border: 0; border-radius: 26px; box-shadow: 0 20px 40px -30px rgba(139, 107, 255, 0.55), inset 0 1px 0 #fff;
  backdrop-filter: none;
}
html[data-theme] #page-stats .stat:before { content: none; }
html[data-theme] #page-stats .stat strong { font-size: 34px; font-weight: 800; color: #241a2e; background: none; -webkit-text-fill-color: #241a2e; }
html[data-theme] #page-stats .stat label, html[data-theme] #page-stats .stat em { color: #4a3559; }
html[data-theme] #page-stats .card { border-radius: 30px; box-shadow: 0 26px 50px -38px rgba(255, 119, 200, 0.45); }
html[data-theme] #page-stats .stat-bar { border-radius: 999px; background: #fff0f8; padding: 10px 16px; }
html[data-theme] #page-stats .stat-track { height: 8px; border-radius: 999px; background: #ffe0ec; box-shadow: none; }
html[data-theme] #page-stats .stat-track i {
  border-radius: 999px; background: linear-gradient(90deg, #ff77c8, #8b6bff); box-shadow: 0 3px 10px rgba(255, 119, 200, 0.5);
}
html[data-theme] #page-stats .stats-year-head {
  margin-top: 30px; border: 0; border-radius: 36px; padding: 30px 32px;
  background: linear-gradient(140deg, #ffffff, #fff3d6 55%, #ffe4f3);
  box-shadow: 0 30px 60px -42px rgba(255, 161, 61, 0.5);
}
html[data-theme] #page-stats .year-title {
  font-size: 44px; letter-spacing: -1px;
  background: linear-gradient(96deg, #ff4fb0, #ffb347 55%, #8b6bff);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
html[data-theme] #page-stats #echoYear {
  border: 0; border-radius: 999px; background: #ffe14d; color: #241a2e; font-weight: 800; padding: 10px 18px;
}
html[data-theme] #page-stats #echoBody { padding: 24px; }

/* 设置 */
html[data-theme] .ct-box { border: 0; border-radius: 26px; background: #fff; box-shadow: 0 22px 44px -34px rgba(139, 107, 255, 0.5); }
html[data-theme] .ct-code, html[data-theme] #ctCss, html[data-theme] #ctHtml {
  border: 1px solid #ffd9e6; border-radius: 18px; background: #fff8fb; color: #3d2c4c;
}

/* 播放舱：半透明糖霜 */
@media (min-width: 901px) {
  html[data-theme] body .dock {
    left: 50%; right: auto; bottom: 18px; translate: -50% 0;
    width: min(880px, calc(100vw - 40px)); max-width: calc(100vw - 24px);
    padding: 14px 24px 16px; border: 0; border-radius: 32px;
    background: linear-gradient(150deg, rgba(255, 255, 255, 0.92), rgba(255, 240, 250, 0.94));
    box-shadow: 0 34px 70px -36px rgba(255, 119, 200, 0.6), inset 0 1px 0 #fff;
    backdrop-filter: blur(26px) saturate(180%);
  }
  html[data-theme] .mini-player { left: 292px; }
}
html[data-theme] .dock .playbtn { border-radius: 50%; background: linear-gradient(140deg, #ff77c8, #8b6bff); color: #fff; box-shadow: 0 12px 26px -14px rgba(139, 107, 255, 0.8); }
html[data-theme] .mini-player { border: 0; border-radius: 999px; background: rgba(255, 255, 255, 0.9); box-shadow: 0 22px 44px -30px rgba(255, 119, 200, 0.6); }

html[data-theme] .cue.active .word { color: #2b1338; background: #ffe14d; border-radius: 6px; }
html[data-theme] ::-webkit-scrollbar-thumb { background: #ffb3d9; border-radius: 999px; }

/* ---------- 12. 壁纸模式：全屏字幕层 ---------- */
html[data-theme] .wallpaper { background: linear-gradient(150deg, #fff6f1 0%, #ffe6f3 46%, #e9e4ff 100%); color: #241a2e; }
html[data-theme] .wp-bg { filter: blur(36px) saturate(180%) brightness(1.32) contrast(.95); opacity: .34; }
html[data-theme] .wp-shade { background: linear-gradient(90deg, rgba(255,246,241,.94) 0%, rgba(255,240,248,.86) 52%, rgba(240,238,255,.74) 78%, rgba(255,246,241,.94) 100%), radial-gradient(70% 60% at 82% 18%, rgba(255,119,200,.28), transparent 66%); }
html[data-theme] .wp-kicker { color: #8b6bff; font-weight:800;letter-spacing:.18em; }
html[data-theme] .wp-title { color: #241a2e; font-weight:800;letter-spacing:-.035em; }
html[data-theme] .wp-cue.past, html[data-theme] .wp-cue.future { color: rgba(36,26,46,.7); }
html[data-theme] .wp-cue.active::before { background: linear-gradient(180deg, #ff77c8, #8b6bff); box-shadow: 0 0 28px rgba(255,119,200,.55); width:clamp(5px,.36vw,7px);border-radius:6px; }
html[data-theme] .wp-cue.active .wp-en { color: #241a2e; text-shadow: 0 3px 20px rgba(255,119,200,.28); font-weight:800; }
html[data-theme] .wp-word.past { color: #241a2e; }
html[data-theme] .wp-word.active { color: #8b6bff; background-image: linear-gradient(180deg, transparent 58%, rgba(255,119,200,.5) 58%, rgba(139,107,255,.32) 94%, transparent 94%); text-shadow: 0 0 22px rgba(255,119,200,.45); border-radius:6px; }
html[data-theme] .wp-zh { color: rgba(36,26,46,.62); font-weight:500; }
html[data-theme] .wp-label { color: rgba(36,26,46,.42); }
html[data-theme] .wpbtn { background: #ffffff; border-color: #ffd9e6; color: #241a2e; border-radius:999px;box-shadow:0 12px 26px -14px rgba(255,119,200,.8);font-weight:700; }
html[data-theme] .wpbtn:hover { background: #ff77c8; border-color: #ff77c8; color: #ffffff; }

/* ---------- 13. 底栏几何：与内置对齐 ---------- */
html[data-theme] body .dock {
  left: 50% !important; right: auto !important; translate: -50% 0 !important; bottom: 16px !important;
  width: min(1040px, calc(100% - 40px)) !important; max-width: none !important; margin: 0 !important;
}
html[data-theme] body.player-open .dock {
  left: 0 !important; right: 0 !important; translate: none !important; bottom: 16px !important;
  width: auto !important; max-width: min(880px, calc(100vw - 40px)) !important; margin: 0 auto !important;
}
html[data-theme] .mini-player { left: 258px; right: 20px; }
@media (max-width: 1180px) { html[data-theme] .mini-player { left: 220px; } }
@media (max-width: 900px) { html[data-theme] .mini-player { left: 10px; right: 10px; bottom: 64px; } }
html[data-theme] body.nav-collapsed .mini-player { left: 20px; right: 20px; }

/* ---------- 14. 播放工具面板（更多）：按主题重绘 ---------- */

html[data-theme] .dshead h4 { color: var(--soft, var(--muted)); }
html[data-theme] .dstile { background: var(--panel2, var(--panel)); border: 1px solid var(--line); color: var(--ink); border-radius: 12px; }
html[data-theme] .dstile svg { stroke: var(--muted); }
html[data-theme] .dstile:hover { background: var(--hover, var(--panel2)); border-color: var(--accent); color: var(--ink); }
html[data-theme] .dstile:hover svg { stroke: var(--accent); }
html[data-theme] .dstile[aria-pressed="true"], html[data-theme] .dstile[aria-expanded="true"] { border-color: var(--accent); }
html[data-theme] .dslabel { color: var(--muted); }
html[data-theme] .dspill, html[data-theme] .dsmute { background: var(--panel2, var(--panel)); border-color: var(--line); color: var(--soft, var(--ink)); }
html[data-theme] .dspill.on { color: var(--accent); border-color: var(--accent); }
html[data-theme] .dsrange { accent-color: var(--accent); }
html[data-theme] .iconbtn { background: var(--panel2, var(--panel)); border: 1px solid var(--line); color: var(--muted); }
